import {frozenCases} from './hybrid-evidence.js';
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='beforeroll-design-v2-editorial-studio';
const params=new URLSearchParams(location.search);
const readStore=()=>{try{return JSON.parse(localStorage.getItem(STORE)??'null')??{};}catch{return {};}};
const saved=readStore();
const s={view:'opening',caseId:params.get('hcase')==='U02'?'U02':'U01',sceneId:params.get('hscene')??'S47',unit:Number(params.get('unit')??1),scenario:params.get('scenario')??'recorded',epoch:saved.epochs?.[params.get('hcase')==='U02'?'U02':'U01']??1,epochs:saved.epochs??{U01:1,U02:1},query:'',page:0,historyQuery:'',historyKind:'all',historyPage:0,workFilter:'all',workPage:0,menu:false,sceneMenu:false,notice:'',error:'',drafts:saved.drafts??{},staged:saved.staged??[],reviews:saved.reviews??[],conditions:saved.conditions??{},intake:saved.intake??null,verified:false,revisionPreview:false,recovery:'valid',recoveryVerified:false,recovered:saved.recovered??[],historyStress:false,studyOpen:false};
let notifyScreen=()=>{};
const active=()=>document.body.classList.contains('editorial-studio');
const pack=()=>frozenCases.find(x=>x.case.id===s.caseId);
const clauses=()=>pack().case.permit.split('\n');
const meta=()=>s.caseId==='U01'?{name:'Riverton Archive',ref:'HW-18',day:'08 Nov 2026',location:'Archive Atrium',short:'Tracking carriage',first:47,second:48,heading:'A camera move. A floor restriction.',activity:'wheeled dolly',sourceTerm:'pressure-bearing wheeled camera platforms',scope:'AD-4',condition:'Protective boards and an on-site registrar',requestAction:'Obtain an issued Scene 48 amendment.'}:{name:'North Arcade',ref:'VA-09',day:'09 Nov 2026',location:'North Arcade',short:'Market-set booth',first:62,second:63,heading:'A market set. A public passage.',activity:'foldout prop merchant booth',sourceTerm:'temporary scenic installations that redirect visitors',scope:'RP-7',condition:'A two-metre clear walkway maintained by stewards',requestAction:'Obtain an issued Scene 63 route plan.'};
const realScenes=()=>pack().case.scenes.map((row,i)=>({id:'S'+(meta().first+i),row,number:meta().first+i,location:row.split(' | ')[1],time:row.split(' | ')[2],activity:row.split(' | ')[3],generated:false,index:i}));
const scenes=()=>s.scenario==='many'?[...realScenes(),...Array.from({length:118},(_,i)=>({id:'T'+(101+i),row:`Design test scene ${101+i} | Test location | time not recorded | Inspect a generated production activity.`,number:101+i,location:'Design test location',time:'Not dated',activity:'Inspect a generated production activity. No model request or response exists for this row.',generated:true,index:null}))]:realScenes();
const scene=()=>scenes().find(x=>x.id===s.sceneId)??realScenes()[0];
const recorded=()=>!scene().generated&&!['no-model','stale','long','empty','loading','error'].includes(s.scenario)?pack().recording.scenes[scene().index].scan.results[s.unit]:null;
const frozenResult=(id=s.sceneId,u=s.unit,c=s.caseId)=>{const p=frozenCases.find(x=>x.case.id===c);return p.recording.scenes.find(x=>x.sceneId===id)?.scan.results[u]??null;};
const contextKey=()=>[s.caseId,s.sceneId,s.unit,s.scenario,s.epoch].join(':');
const persist=()=>localStorage.setItem(STORE,JSON.stringify({epochs:s.epochs,drafts:s.drafts,staged:s.staged,reviews:s.reviews,conditions:s.conditions,intake:s.intake,recovered:s.recovered}));
const b=(text,go,cls='h-quiet',attrs='')=>`<button class="${cls}" data-hgo="${go}" ${attrs}>${text}</button>`;
const step=(n,t)=>`<div class="h-step"><span>${n}</span>${t}</div>`;
const pill=(text,kind='')=>`<span class="h-state ${kind}">${text}</span>`;
const digest=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))).map(x=>x.toString(16).padStart(2,'0')).join('');
const sourceText=()=>s.scenario==='long'?Array.from({length:7},(_,i)=>`Design test paragraph ${i+1}. Camera equipment may be moved only after the coordinator has compared the current floor protection plan, load assessment, access route and registrar attendance against the exact scene, date and operating area. This additional text is a generated long-document stress fixture, not a permit or Clocked evidence.`).join('\n\n'):clauses()[s.unit];
const quote=(text=sourceText(),citation=true)=>`<blockquote class="h-quote"><p data-exact-source>${E(text)}</p>${citation?`<cite>${s.scenario==='long'?'Design-only long source · not analyzed':`${meta().ref} · paragraph ${s.unit+1} · original revision 1`}</cite>`:''}</blockquote>`;
const selectedLatest=()=>s.reviews.filter(r=>r.caseId===s.caseId&&r.sceneId===s.sceneId&&r.unit===s.unit&&r.epoch===s.epoch).at(-1);
function updateURL(){const u=new URL(location);u.searchParams.set('concept','editorial-studio');u.searchParams.set('screen',s.view);u.searchParams.set('hcase',s.caseId);u.searchParams.set('hscene',s.sceneId);u.searchParams.set('unit',s.unit);if(s.scenario!=='recorded')u.searchParams.set('scenario',s.scenario);else u.searchParams.delete('scenario');window.history.replaceState(null,'',u);notifyScreen(s.view);}
function go(view,{focus=true}={}){captureDraft();s.view=view;s.notice='';s.error='';render();if(focus){document.querySelector('#main')?.focus();window.scrollTo(0,0);}}
function captureDraft(){const f=document.querySelector('#h-review-form');if(f){const d=new FormData(f);s.drafts[contextKey()]={reviewer:d.get('reviewer'),decision:d.get('decision'),reason:d.get('reason')};persist();}}
function shell(content){const m=meta();const menu=s.menu?`<section class="h-production-menu" aria-label="Choose production"><h2>Your productions</h2>${frozenCases.map(p=>b(`${p.case.id==='U01'?'Riverton Archive':'North Arcade'}<small>Fictional case ${p.case.id} · genuine historical recording</small>`,'case-'+p.case.id,'h-production-option')).join('')}${b('New empty production','empty','h-production-option')}<p>${s.staged.length?'Apply or remove staged decisions before changing production.':'Design sandbox only. No actual production store is opened.'}</p></section>`:'';
 return `<div class="h-root"><header class="h-top"><button class="h-brand" data-hgo="opening" aria-label="BeforeRoll production overview">BeforeRoll<span>.</span></button><button class="h-production" data-hgo="picker" aria-expanded="${s.menu}">${s.scenario==='empty'?'Untitled production':m.name}<span>⌄</span></button><nav aria-label="Workspace">${[['opening','Overview'],['discovery','Scenes'],['workflow','Work'],['depth','Evidence']].map(([v,t])=>b(t,v,'h-nav',`aria-current="${s.view===v?'page':'false'}"`)).join('')}</nav>${s.staged.length?b(`${s.staged.length} staged`,'preview','h-session-link'):''}</header>${menu}<div class="h-context"><span>${s.scenario==='empty'?'New production':`${m.name} / ${m.day}`}</span><span>Fictional study · ${s.scenario==='recorded'?'recorded Clocked / older contract':'design state: '+E(s.scenario)} · zero live calls</span><details class="h-study" ${s.studyOpen?'open':''}><summary>Study controls</summary><label>Test condition<select id="h-scenario">${[['recorded','Original recorded case'],['many','120 scenes · design stress'],['no-model','No model evidence'],['long','Long source · design stress'],['historical','Historical finding'],['stale','Stale / changed source'],['empty','Empty production'],['loading','Loading specimen'],['error','Unavailable / error']].map(([v,t])=>`<option value="${v}" ${v===s.scenario?'selected':''}>${t}</option>`).join('')}</select></label><a href="font-study.html">Rendered type comparison ↗</a><p>Generated additions have no provider responses.</p></details></div><main id="main" tabindex="-1">${s.error?`<div class="h-feedback h-error" role="alert">${E(s.error)}</div>`:''}${s.notice?`<div class="h-feedback" role="status">${E(s.notice)}</div>`:''}${content}</main><footer class="h-footer"><span>BeforeRoll · Editorial Intelligence Studio</span><span>Model interpretation · original language · human work</span></footer></div>`;
}
function opening(){if(s.scenario==='empty')return empty();const m=meta();return `<div class="h-overview"><div class="h-opening-copy"><span class="h-kicker">Before the first take</span><h1>Know what the shot<br><em>depends on.</em></h1><p>Clocked connects the activity on your call sheet with the language in your permit. Investigate the source. Keep the next human action in view.</p><div class="h-actions">${b(`Investigate Scene ${m.first} →`,'discovery','h-primary')}${b('Open production work','workflow','h-link')}</div></div><article class="h-opening-case"><div class="h-case-head"><span>One scene. Two vocabularies.</span><span>Scene ${m.first}</span></div><div class="h-vocabulary"><div><small>Planned activity</small><strong>${m.activity}</strong></div><span class="h-connect" aria-label="Clocked relationship">↔</span><div><small>Original permit language</small><strong>${m.sourceTerm}</strong></div></div><p class="h-explainer">Clocked's recorded finding links the scene to the restriction. The documentary exception and its conditions still need human review.</p><div class="h-record-line"><span>Recorded finding</span><p>${E(pack().recording.scenes[0].scan.results[1].finding.title)}</p></div><div class="h-case-foot">${b('Compare exception and request →','exception','h-link')}<small>Reading guide above · exact recording available</small></div></article></div><section class="h-production-list"><div class="h-section-title"><h2>Production desk</h2>${b('Create a production','empty')}</div>${frozenCases.map(p=>`<button data-hgo="case-${p.case.id}" class="h-production-row"><span class="h-document-icon">${p.case.id}</span><span><strong>${p.case.id==='U01'?'Riverton Archive':'North Arcade'}</strong><small>${p.case.id==='U01'?'Floor protection / Scenes 47–48':'Public passage / Scenes 62–63'}</small></span><span>2 scenes · 1 original permit</span><span>Open ↗</span></button>`).join('')}</section>`;}
function empty(){return `<div class="h-empty"><span class="h-kicker">New production</span><h1>Start with the originals.</h1><p>Import a permit and a call sheet. Keep their exact source identity before investigating what the crew plans to do.</p><div class="h-empty-path"><span>01<br><b>Add source documents</b></span><span>02<br><b>Verify the text</b></span><span>03<br><b>Review scene checks</b></span></div>${b('Import fictional sources →','intake','h-primary')}${b('Explore the recorded example','reset-case','h-link')}<small>No documents, scene checks or model results have been created for this empty design state.</small></div>`;}
function register(){const all=scenes(),filtered=all.filter(x=>`${x.id} Scene ${x.number} ${x.row} ${x.location} ${x.activity}`.toLowerCase().includes(s.query.toLowerCase()));const start=Math.min(s.page*20,Math.max(0,Math.floor((filtered.length-1)/20)*20));const displayed=filtered.slice(start,start+20);return `<aside class="h-register ${s.sceneMenu?'is-open':''}"><div class="h-register-title"><h2>Scenes</h2><span>${all.length}</span>${s.sceneMenu?b('Close search','toggle-scenes','h-register-close'):''}</div><label class="h-search">Find a scene<input id="h-scene-search" type="search" value="${E(s.query)}" placeholder="Number, place or activity"></label><nav aria-label="Scene register">${displayed.map(x=>`<button data-hscene="${x.id}" aria-current="${scene().id===x.id?'true':'false'}"><b>${x.number}</b><span><strong>${x.generated?'Design scene':x.index===0?meta().short:s.caseId==='U01'?'Rolling platform':'Across-passage booth'}</strong><small>${x.time}</small><small>${x.generated?'Test row · not analyzed':x.index===0?'Scoped exception to check':'Unissued request only'}</small></span></button>`).join('')||'<p>No matching scenes. Clear the search to return to the register.</p>'}</nav><div class="h-page"><span>${filtered.length?`${start+1}–${Math.min(start+20,filtered.length)} / ${filtered.length}`:'0 / 0'}</span>${b('←','scene-prev','h-page-button',`aria-label="Previous scenes" ${start===0?'disabled':''}`)}${b('→','scene-next','h-page-button',`aria-label="Next scenes" ${start+20>=filtered.length?'disabled':''}`)}</div><p class="h-small">${s.scenario==='many'?'118 additional rows are generated test material. No model results exist for them.':'Source-bound selection stays with the investigation.'}</p>${b('Production work ↗','workflow','h-link')}</aside>`;}
function mobileScene(){return `<div class="h-mobile-scene"><label>Scene<select id="h-mobile-scene">${scenes().map(x=>`<option value="${x.id}" ${x.id===scene().id?'selected':''}>${x.number} · ${x.generated?'Design test':x.index===0?meta().short:'Unissued request'}</option>`).join('')}</select></label>${b(s.sceneMenu?'Hide register':'Find a scene','toggle-scenes','h-quiet',`aria-expanded="${s.sceneMenu}"`)}</div>`;}
function scenarioNotice(){return s.scenario==='stale'?`<div class="h-feedback h-attention"><strong>Earlier finding · current sources need reassessment</strong><p>Design revision scenario. The original recording is retained as earlier evidence; it is not a result for the changed source.</p>${b('Inspect earlier recording','history','h-link')}</div>`:s.scenario==='historical'?`<div class="h-feedback"><strong>Historical view · original source revision 1</strong><p>This is the genuine earlier-contract recording. Its historic identity remains visible; it is not new analysis.</p></div>`:'';}
function modelBlock(){const r=recorded();const m=meta();if(!r)return `<section class="h-model" data-role="model">${step('02','Clocked intelligence')}<h3>${scene().generated?'This test scene has not been analyzed.':s.scenario==='stale'?'No result for the changed source.':'No current model evidence.'}</h3><p>${s.scenario==='long'?'This longer text is design material. No Clocked result is attached to it.':'Inspect the original document and prepare source checks. No conclusion is inferred from an absent result.'}</p>${b('Inspect analysis availability','analysis','h-link')}</section>`;
return `<section class="h-model" data-role="model">${step('02','Clocked intelligence')}<div class="h-relationship"><span>${s.unit===1?(scene().index===1?(s.caseId==='U01'?'rolling camera platform':'portable booth across the central pedestrian lane'):m.activity):'Scene '+scene().number}</span><span class="h-connect">↔</span><span>${s.unit===1?m.sourceTerm:['location consent','scoped exception','unsigned request'][s.unit===0?0:s.unit===2?1:2]}</span></div><p class="h-guide">Reading guide · design-authored. ${s.unit===1?'Different words may describe the same production activity. Inspect the linked passage.':'Read this passage against the exact scene; its scope cannot be extended by resemblance.'}</p><div class="h-record-line"><span>Genuine recorded finding</span><p>${E(r.finding.title)}</p></div><details><summary>Recorded model output</summary><p>${E(r.finding.explanation)}</p><dl><dt>Activity link · raw return</dt><dd>${r.finding.relevance}</dd><dt>Scene grant · raw return</dt><dd>${r.finding.grant}</dd></dl><p>Uncalibrated model outputs. No numerical return establishes documentary authority.</p><code>${E(r.finding.code)}</code></details></section>`;}
function nextAction(){const m=meta(),x=scene();return `<section class="h-next" id="h-next-action" tabindex="-1">${step('04','Human action')}<div><h3>${x.generated?'Investigate the original source for this test activity.':x.index===0?`Check ${m.scope}'s scene scope and conditions.`:m.requestAction}</h3><p>${x.generated?'No model assessment or scene-specific documentary exception is supplied.':x.index===0?m.condition+' still need human verification.':'The request is unissued. A similar activity does not inherit the other scene’s exception.'}</p>${selectedLatest()?pill('Prototype human review recorded','h-human'):''}</div><div class="h-next-buttons">${b('Record source review →','review','h-primary',`${['long','stale'].includes(s.scenario)?'disabled':''}`)}${b('Compare exception and request →','exception','h-link')}</div></section>`;}
function discovery(){const x=scene();return `<div class="h-desk">${register()}<section class="h-investigate">${mobileScene()}${scenarioNotice()}<div class="h-page-title"><div><span class="h-kicker">Scene ${x.number} / ${E(x.location)}</span><h1><span class="h-full-title">${x.generated?'An unexamined production activity.':meta().heading}</span><span class="h-compact-title">${x.generated?'Unexamined activity':s.caseId==='U01'?'Floor restriction':'Public passage'}</span></h1></div><a class="h-action-jump" href="#h-next-action">Next action ↓</a></div><div class="h-investigation-grid"><div><section class="h-plan" data-role="plan">${step('01','Planned activity')}<p class="h-scene-activity" data-exact-scene>${E(x.activity)}</p><small>${E(x.time)} · ${x.generated?'Generated design row':`Call sheet / Scene ${x.number}`}</small></section>${modelBlock()}</div><div class="h-evidence-action"><section class="h-source" data-role="source">${step('03','Original documentary language')}<label class="h-passage-select">Passage<select id="h-source-unit">${clauses().map((_,i)=>`<option value="${i}" ${i===s.unit?'selected':''}>${i+1} · ${['Location consent','Activity restriction','Scoped exception','Unissued request'][i]}</option>`).join('')}</select></label>${quote()}<div class="h-source-tools">${b('Read original & provenance ↗','depth','h-link')}<small>Source language does not authenticate a signature.</small></div></section>${nextAction()}</div></div></section></div>`;}
function exception(){const m=meta();const column=(n,u,first)=>`<article class="h-compare-column"><div class="h-compare-cell h-compare-title"><span>Scene ${n}</span><h2>${first?'Explicitly named':'Request only'}</h2>${pill(first?(s.caseId==='U01'?'Document says “SIGNED ADDENDUM”':'Document says “APPROVED ROUTE PLAN”'):'Document says no revised grant was issued',first?'':'h-attention')}</div><div class="h-compare-cell"><span class="h-kicker">Original paragraph ${u+1}</span>${quote(clauses()[u],false)}<small>${m.ref} · paragraph ${u+1} · original revision 1</small></div><div class="h-compare-cell"><h3>${first?'Check the conditions':'Seek an issued extension'}</h3><p>${first?m.condition+'. Verify scope, original language and fulfilment with a responsible person.':'The request does not establish permission for Scene '+n+'. General consent does not override this activity restriction.'}</p>${b('Investigate Scene '+n+' →',first?'investigate-first':'investigate-second','h-primary')}</div></article>`;return `<div class="h-content-wide"><div class="h-page-title"><div><span class="h-kicker">Documentary comparison / ${m.ref}</span><h1>One location. Two different scopes.</h1><p>Compare what the original actually says before extending an exception.</p></div>${b('Return to scene →','discovery','h-link')}</div><div class="h-shared-source"><span>Underlying restriction</span><p>${E(clauses()[1])}</p></div><div class="h-compare">${column(m.first,2,true)}${column(m.second,3,false)}</div><p class="h-small">Documentary reading guide, not a new model response or signature authentication. Clocked’s exact outputs remain attached to each scene and paragraph.</p></div>`;}
function workItems(){const m=meta();let a=[{id:'condition-1',scene:'S'+m.first,title:'Verify '+m.condition.toLowerCase(),source:m.scope+' / paragraph 3',kind:'condition'},{id:'condition-2',scene:'S'+m.second,title:'Obtain the issued extension',source:m.ref+' / paragraph 4',kind:'source'},{id:'date',scene:'S'+m.first,title:'Confirm dated scene plan',source:'Call sheet / timezone and overnight intent',kind:'schedule'}];if(s.scenario==='many')a.push(...scenes().filter(x=>x.generated).map(x=>({id:x.id,scene:x.id,title:'Inspect generated scene source coverage',source:'Design test row / no model evidence',kind:'review'})));return a;}
function workflow(){const rows=workItems().filter(x=>s.workFilter==='all'||x.kind===s.workFilter);const page=rows.slice(s.workPage*15,s.workPage*15+15);return `<div class="h-content-wide"><div class="h-page-title"><div><span class="h-kicker">Production work / ${meta().day}</span><h1>What the shoot still depends on.</h1><p>Work follows the source. Recording completion never establishes filming permission.</p></div>${b('Review session','preview','h-quiet')}</div><div class="h-work-layout"><section><div class="h-work-tools"><h2>Outstanding work</h2><label>Work type<select id="h-work-filter">${[['all','All work'],['condition','Conditions'],['source','Source needed'],['schedule','Scene dates'],['review','Scene review']].map(([v,t])=>`<option value="${v}" ${s.workFilter===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="h-work-register">${page.map(x=>`<button data-hcondition="${x.id}" class="h-work-row"><b>${x.scene.replace(/^S/,'')}</b><span><strong>${E(x.title)}</strong><small>${E(x.source)}</small></span><span class="h-work-status">${s.conditions[s.caseId+':'+x.id]?.decision==='Human confirmed — not authority'?'Human confirmation recorded':s.conditions[s.caseId+':'+x.id]?.decision??(x.kind==='source'?'Source needed':'Open for human work')}</span><span>↗</span></button>`).join('')||'<div class="h-state-empty">No work matches this filter. Other unresolved work remains in the full register.</div>'}</div><div class="h-page"><span>${rows.length?`${s.workPage*15+1}–${Math.min(s.workPage*15+15,rows.length)} / ${rows.length}`:'0 / 0'} work items</span>${b('Previous','work-prev','h-page-button',`${s.workPage===0?'disabled':''}`)}${b('Next','work-next','h-page-button',`${s.workPage*15+15>=rows.length?'disabled':''}`)}</div></section><aside class="h-pathways"><h2>Production pathways</h2>${[['intake','Import & verify'],['analysis','Source checks'],['review','Human review'],['revision','Source revision'],['history','Complete history'],['export','Export & recovery']].map(([v,t])=>b(t+' ↗',v,'h-path-link')).join('')}</aside></div></div>`;}
function condition(){const x=workItems().find(x=>x.id===s.selectedCondition)??workItems()[0];return `<div class="h-content"><span class="h-kicker">Source-bound production work / ${x.scene}</span><h1>${E(x.title)}</h1><p>${E(x.source)}</p><div class="h-two"><section class="h-reader">${quote(clauses()[x.kind==='source'?3:2])}<p>Human verification tracks operational work. It does not authenticate this source or establish permission.</p>${b('Investigate this scene','condition-scene','h-link')}</section><form id="h-condition-form" class="h-form"><h2>Record the follow-through</h2><label>Reviewer<input name="reviewer" value="${E(s.conditions[s.caseId+':'+x.id]?.reviewer??'')}" required maxlength="150"></label>${x.kind==='schedule'?'<label>Scene date<input name="date" type="date" value="'+E(s.conditions[s.caseId+':'+x.id]?.date??'')+'" required></label><label>Timezone<input name="timezone" value="Africa/Lagos" required></label>':''}<label>Work decision<select name="decision">${['Needs source evidence','Human confirmed — not authority','Blocked'].map(v=>`<option ${s.conditions[s.caseId+':'+x.id]?.decision===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Evidence and remaining work<textarea name="reason" required minlength="8" rows="4">${E(s.conditions[s.caseId+':'+x.id]?.reason??'')}</textarea></label><button class="h-primary">Record prototype work</button></form></div></div>`;}
function evidenceTabs(){return `<nav class="h-evidence-tabs" aria-label="Evidence views">${[['documents','Sources'],['history','History'],['export','Exports & recovery']].map(([v,t])=>b(t,v,'h-tab',`aria-current="${s.view===v?'page':'false'}"`)).join('')}</nav>`;}
function provenance(result=recorded()){return `<details class="h-provenance"><summary>Exact provenance & model fields</summary><dl><dt>Evidence origin</dt><dd>${s.scenario==='long'?'Design-only fixture · no provider recording':result?'Owner-recorded · older request contract':'No current model evidence · original source retained'}</dd><dt>Source</dt><dd>${s.scenario==='long'?'Generated long-document fixture':E(meta().ref)+' · original revision 1'}</dd><dt>Source SHA-256</dt><dd><code>${s.scenario==='long'?'No frozen source identity for this generated text':pack().case.permitSha256}</code></dd><dt>Scene SHA-256</dt><dd><code>${scene().generated||s.scenario==='long'?'No frozen model scene identity for this design fixture':pack().case.sceneSha256[scene().index]}</code></dd><dt>Recorded request SHA-256</dt><dd><code>${result?.requestHash??'No current recorded request for this selection'}</code></dd></dl>${result?`<h3>Original recorded fields</h3><pre>${E(JSON.stringify(result.modelAnswers,null,2))}</pre><p>${E(result.finding.explanation)}</p>`:'<p>No model output is fabricated for this state.</p>'}</details>`;}
function depth(){return `<div class="h-content-wide">${evidenceTabs()}<div class="h-page-title"><div><span class="h-kicker">Evidence / Scene ${scene().number} / paragraph ${s.unit+1}</span><h1>Read the original. Trace the finding.</h1></div>${b('Return to scene →','discovery','h-link')}</div><div class="h-evidence-layout"><aside class="h-source-index"><h2>${meta().ref}</h2><p>Original source revision 1</p><nav aria-label="Source passages">${clauses().map((_,i)=>`<button data-hunit="${i}" aria-current="${s.unit===i?'true':'false'}"><span>0${i+1}</span>${['Location consent','Activity restriction','Scoped exception','Unissued request'][i]}</button>`).join('')}</nav><label>Evidence scene<select id="h-evidence-scene">${realScenes().map(x=>`<option value="${x.id}" ${scene().id===x.id?'selected':''}>Scene ${x.number}</option>`).join('')}</select></label></aside><article class="h-reader">${s.scenario==='historical'?pill('Historical / original recorded identity'):s.scenario==='stale'?pill('Earlier source shown / no result for changed source','h-attention'):pill(s.scenario==='long'?'Design-only source':'Exact original wording')}${quote()}${recorded()?`<div class="h-record-line"><span>Recorded Clocked finding</span><h3>${E(recorded().finding.title)}</h3><p>${E(recorded().finding.explanation)}</p></div>`:'<p>No current model result is attached to this text.</p>'}${provenance()}<details><summary>${s.scenario==='long'?'Frozen reference text · separate from this fixture':'Complete original text · four passages'}</summary>${clauses().map((text,i)=>`<section class="h-full-paragraph"><small>Paragraph ${i+1}</small><p>${E(text)}</p></section>`).join('')}</details><div class="h-actions">${b('Record source review →','review','h-primary',`${['long','stale'].includes(s.scenario)?'disabled':''}`)}${b('Review history','history','h-link')}</div></article></div></div>`;}
function review(){const d=s.drafts[contextKey()]??{};return `<div class="h-content"><div class="h-page-title"><div><span class="h-kicker">Human review / Scene ${scene().number}</span><h1>Your reading, attached to this source.</h1></div>${b('Back to scene','discovery','h-link')}</div><div class="h-two"><section class="h-review-source"><div class="h-source-heading">${meta().ref} / paragraph ${s.unit+1}<span>Original revision 1</span></div>${quote()}<p class="h-small">Exact selected scene: ${E(scene().row)}</p>${recorded()?`<p class="h-small">Recorded finding: ${E(recorded().finding.title)}</p>`:'<p class="h-small">No current model evidence. Human source review remains separate.</p>'}</section><form id="h-review-form" class="h-form"><h2>Record a source review</h2><label>Your name<input name="reviewer" value="${E(d.reviewer??'')}" required maxlength="150" autocomplete="off"></label><label>Decision<select name="decision">${['Needs source evidence','Acknowledged for follow-up','Human-reviewed (not clearance)'].map(t=>`<option ${d.decision===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Rationale and next action<textarea name="reason" required minlength="8" maxlength="3000" rows="5">${E(d.reason??'')}</textarea></label><button class="h-primary">Stage exact-source review →</button><small>Draft follows this exact scene and passage. Application is a separate, explicit step.</small></form></div></div>`;}
function preview(){return `<div class="h-content"><div class="h-page-title"><div><span class="h-kicker">Human review session / ${s.staged.length} staged</span><h1>Inspect. Verify. Then apply.</h1><p>Design sandbox checks only; the accepted engine enforces its own atomic version contract.</p></div></div>${s.staged.length?s.staged.map((r,i)=>`<article class="h-staged"><div class="h-source-heading">Scene ${r.sceneId.replace('S','')} / ${r.ref} / paragraph ${r.unit+1}<span>${E(r.decision)}</span></div><blockquote class="h-quote"><p>${E(r.quote)}</p></blockquote><p>${E(r.reviewer)} — ${E(r.reason)}</p><small>${r.caseId} / original source revision 1 / exact source identity retained</small>${b('Remove this staged review','remove-'+i,'h-link')}</article>`).join(''):'<div class="h-state-empty"><h2>No staged decisions.</h2><p>Open an exact scene/source review to stage a reasoned decision.</p></div>'}<div class="h-session-actions">${b(s.verified?'Selected sources verified':'Verify selected sources','verify','h-quiet',`${!s.staged.length?'disabled':''}`)}${b('Apply prototype review','apply','h-primary',`${!s.staged.length?'disabled':''}`)}${b('Return to scene','discovery','h-link')}</div></div>`;}
function documents(){return `<div class="h-content-wide">${evidenceTabs()}<div class="h-page-title"><div><span class="h-kicker">Original sources / ${meta().name}</span><h1>Documents, with their boundaries.</h1></div>${b('Import fictional source','intake','h-primary')}</div><div class="h-document-register"><article><span class="h-document-icon">01</span><div><h2>${meta().ref} / filming consent</h2><p>Original revision 1 · 4 exact passages · includes consent, restriction, scoped exception and request language.</p><small>Claimed documentary role and authenticity still require human review.</small></div>${b('Read original & provenance ↗','depth','h-link')}${b('Preview a source revision','revision','h-quiet')}</article><article><span class="h-document-icon">02</span><div><h2>Original scene register</h2><p>Scenes ${meta().first} and ${meta().second} · exact frozen rows</p><details><summary>Read original call-sheet rows</summary>${pack().case.scenes.map(t=>`<p>${E(t)}</p>`).join('')}</details></div>${b('Investigate scenes','discovery','h-link')}</article></div>${s.intake?`<div class="h-feedback">Prototype intake: ${E(s.intake.name)} · ${s.intake.reviewed?'transcription review recorded':'verification pending'}. No production file store changed.</div>`:''}</div>`;}
function intake(){return `<div class="h-content"><span class="h-kicker">Source intake / fictional material only</span><h1>Keep the original in sight.</h1><p>This interactive design intake reads a local text fixture in your browser. PDF/DOCX extraction, custody and storage remain the accepted engine’s responsibility.</p><form id="h-intake-form" class="h-form"><label>Fictional original text file<input id="h-intake-file" type="file" accept=".txt,.md"></label><p class="h-small">Use the included <a href="hybrid-demo-permit.txt" download>U01 fictional source fixture</a>. No upload or provider request occurs.</p>${s.intake?`<div class="h-source-heading">${E(s.intake.name)}<span>${s.intake.bytes} bytes</span></div><details open><summary>Original text preview</summary><pre>${E(s.intake.text)}</pre></details><details><summary>Original byte identity</summary><code>${s.intake.sha256}</code></details><label>Transcription reviewer<input name="reviewer" required maxlength="150"></label><label class="h-check"><input type="checkbox" name="attest" required>I compared this displayed text with the selected fictional original.</label><button class="h-primary">Record prototype verification</button>`:'<div class="h-state-empty">Choose the fictional text original to inspect its byte identity and text before verification.</div>'}</form>${b('Return to source register','documents','h-link')}</div>`;}
function historyRows(){const models=pack().recording.scenes.flatMap((x,i)=>x.scan.results.map((r,u)=>({kind:'model',id:`${s.caseId}:${x.sceneId}:${u}`,sceneId:x.sceneId,unit:u,title:r.finding.title,detail:`Original recorded comparison / ${meta().ref} paragraph ${u+1}`,historical:true,design:false})));const humans=s.reviews.filter(x=>x.caseId===s.caseId).map((x,i)=>({...x,kind:'human',id:'human-'+i,title:x.decision,detail:x.reason,historical:x.epoch!==s.epoch,design:true}));const test=s.historyStress?Array.from({length:80},(_,i)=>({kind:'human',id:'test-note-'+i,sceneId:'T'+(101+i),unit:0,title:'Design history note '+(i+1),detail:'Generated interface stress note. No provider output or source authority.',historical:i%2===0,design:true})):[];return [...humans,...models,...test];}
function historyView(){const rows=historyRows().filter(r=>(s.historyKind==='all'||r.kind===s.historyKind||s.historyKind==='historical'&&r.historical)&&`${r.sceneId} ${r.title} ${r.detail}`.toLowerCase().includes(s.historyQuery.toLowerCase()));const page=rows.slice(s.historyPage*15,s.historyPage*15+15);return `<div class="h-content-wide">${evidenceTabs()}<div class="h-page-title"><div><span class="h-kicker">Complete evidence history</span><h1>What was recorded, and against what.</h1><p>Original model evidence remains historical. Human entries below are isolated prototype work.</p></div>${b(s.historyStress?'Hide design history stress':'Add design history stress','history-stress','h-quiet')}</div><form class="h-history-tools" id="h-history-filter"><label>Find a record<input name="query" value="${E(s.historyQuery)}" type="search"></label><label>Record type<select name="kind">${[['all','All records'],['model','Recorded model'],['human','Human / design notes'],['historical','Historical']].map(([v,t])=>`<option value="${v}" ${s.historyKind===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="h-quiet">Filter history</button></form><p class="h-small">${rows.length} matching records · ${historyRows().length} total · this page is not the entire history</p><div class="h-history-list">${page.map(r=>`<button data-hhistory="${r.id}" class="h-history-row"><span>${r.sceneId}</span><span><strong>${E(r.title)}</strong><small>${E(r.detail)}</small></span><span>${r.design?'Design / human entry':'Genuine earlier recording'}<small>${r.historical?'Historical':'Prototype current'}</small></span><span>Inspect ↗</span></button>`).join('')||'<div class="h-state-empty">No matching records. Clear the search or change the record type.</div>'}</div><div class="h-page"><span>${rows.length?`${s.historyPage*15+1}–${Math.min(s.historyPage*15+15,rows.length)}`:'0'} / ${rows.length}</span>${b('Previous history page','history-prev','h-page-button',`${s.historyPage===0?'disabled':''}`)}${b('Next history page','history-next','h-page-button',`${s.historyPage*15+15>=rows.length?'disabled':''}`)}</div></div>`;}
function historyDetail(){const r=historyRows().find(x=>x.id===s.historySelected);if(!r)return historyView();return `<div class="h-content"><span class="h-kicker">Selected history record / ${E(r.id)}</span><h1>${E(r.title)}</h1><div class="h-reader"><p>${E(r.detail)}</p>${pill(r.design?'Prototype / design record':'Genuine historical recording')}${r.kind==='model'?`<blockquote class="h-quote"><p>${E(clauses()[r.unit])}</p><cite>${meta().ref} · paragraph ${r.unit+1} · ${r.sceneId} · original revision 1</cite></blockquote><pre>${E(JSON.stringify(frozenResult(r.sceneId,r.unit)?.modelAnswers,null,2))}</pre><code>${frozenResult(r.sceneId,r.unit)?.requestHash}</code>`:`${r.quote?`<blockquote class="h-quote"><p>${E(r.quote)}</p><cite>${E(r.ref)} · paragraph ${r.unit+1} · ${r.sceneId} · original revision 1</cite></blockquote><code>${r.sourceHash}</code>`:''}<p>${E(r.reason??r.detail)}</p><p>${E(r.reviewer??'Generated design note')}</p>`}</div>${b('Back to complete history','history','h-link')}</div>`;}
function revision(){return `<div class="h-content"><span class="h-kicker">Source revision / design interaction</span><h1>Inspect what would need renewed work.</h1><p>The original recording remains untouched. This is a design-only revision scenario, not an actual source replacement.</p><div class="h-reader"><div class="h-revision-pair"><div><small>Original</small><h2>${meta().ref} · revision 1</h2><p>Frozen original and recorded comparison identities remain available.</p></div><div><small>Proposed design change</small><h2>Renewed source conditions</h2><p>Illustrative revision: request a new load/access assessment. This text has no model response.</p></div></div>${s.revisionPreview?`<div class="h-feedback h-attention"><h3>Impact to present from the engine</h3><p>Affected source checks and reviews become historical. Unaffected evidence is retained. Exact retained/retired/added counts must come from the real server preview; this prototype invents none.</p><p>Prototype verification invalidates on this design-state change.</p></div>${b('Show changed-source state','revision-apply','h-primary')}`:b('Preview revision impact','revision-preview','h-primary')}</div>${b('Return to source register','documents','h-link')}</div>`;}
function analysis(){return `<div class="h-content"><span class="h-kicker">Clocked source checks</span><h1>${s.scenario==='stale'?'Renew checks for changed sources.':'Inspect scope before analysis.'}</h1><div class="h-reader"><h2>Analysis is unavailable in this design sandbox.</h2><p>Original example: two scenes × four source passages. Browse the eight genuine historical comparisons. No fresh provider result exists for generated scenes or changed-source tests.</p><p>In production, present exact task coverage, explicit authorization and budget before dispatch. Unknown billing must retain its fence without automatic retry.</p>${b('Inspect recorded evidence','depth','h-primary')}${b('Return to scene','discovery','h-link')}</div></div>`;}
function exportView(){return `<div class="h-content-wide">${evidenceTabs()}<div class="h-page-title"><div><span class="h-kicker">Exports & recovery</span><h1>Preserve the work and its context.</h1></div></div><div class="h-two"><section class="h-reader"><h2>Design review notes</h2><p>${s.reviews.length} human prototype records. The download is explicitly design notes, not an engine evidence pack or encrypted backup.</p>${b('Download prototype notes','download','h-primary')}<details><summary>Production export contract</summary><p>Current snapshot → exact JSON and readable report → current and historical evidence → separate encrypted lifecycle backup. Stale reviewed exports are refused by the engine.</p></details></section><section class="h-reader"><h2>Recover a separate copy</h2><p>Walk through verification, failure and separate-copy confirmation using a clearly labeled recovery specimen.</p>${b('Inspect recovery specimen','recovery','h-quiet')}<small>No encrypted file is read and no production is restored here.</small></section></div></div>`;}
function recovery(){return `<div class="h-content"><span class="h-kicker">Recovery specimen / design simulation</span><h1>Verify before making a separate copy.</h1><p>This is a design-only interaction. It does not decrypt a backup or access actual production data.</p><div class="h-reader"><label>Recovery condition<select id="h-recovery-condition">${[['valid','Valid design sample'],['wrong','Wrong passphrase / damaged ciphertext'],['missing','Missing original source'],['unknown','Uncertain provider outcome']].map(([v,t])=>`<option value="${v}" ${s.recovery===v?'selected':''}>${t}</option>`).join('')}</select></label>${b('Verify recovery sample','recovery-verify','h-primary')}${s.recoveryVerified&&s.recovery==='valid'?`<div class="h-feedback"><h2>Design inventory ready</h2><p>2 frozen source texts · 8 historical comparisons · prototype human notes. This is not an actual vault/journal inventory.</p></div><form id="h-recovery-form" class="h-form"><label>Type the sample production name<input name="identity" required autocomplete="off" placeholder="${meta().name}"></label><button class="h-primary">Create separate design copy</button></form>`:''}${s.recoveryVerified&&s.recovery==='wrong'?'<div class="h-feedback h-error" role="alert">Verification failed. Check the passphrase or backup integrity. No restore occurred; current work is unchanged.</div>':''}${s.recoveryVerified&&s.recovery==='missing'?'<div class="h-feedback h-error" role="alert">An original is missing from the sample inventory. Reconnect exact bytes before claiming complete recovery.</div>':''}${s.recoveryVerified&&s.recovery==='unknown'?'<div class="h-feedback h-attention">Uncertain provider outcome retained. Inspect the recorded attempt; recovery never retries the request.</div>':''}${s.recovered.length?`<p>${s.recovered.length} separate prototype recovery copies recorded. Originals were not overwritten.</p>`:''}</div>${b('Back to exports','export','h-link')}</div>`;}
function stateView(kind){return `<div class="h-content h-empty"><span class="h-kicker">${kind==='loading'?'Loading specimen':'Unavailable state'} / design material</span><h1>${kind==='loading'?'Gathering the source context.':'The source inventory could not open.'}</h1><p>${kind==='loading'?'Keep the selected production and scene visible while the real snapshot loads. This specimen performs no background request.':'Your selected scene and drafts are retained. Retry the read-only inventory; do not dispatch a model request to repair a source-loading error.'}</p>${kind==='loading'?'<div class="h-skeleton" aria-hidden="true"><span></span><span></span><span></span></div>':''}${b(kind==='loading'?'Show loaded example':'Retry source inventory','reset-case','h-primary')}</div>`;}
function render(){if(!active())return;const previous=document.activeElement;const focusId=previous?.id;const focusGo=previous?.dataset?.hgo;const focusScene=previous?.dataset?.hscene;const focusUnit=previous?.dataset?.hunit;document.title='Editorial Intelligence Studio · BeforeRoll design study';const views={opening,discovery,exception,workflow,depth,review,preview,condition,documents,intake,history:historyView,'history-detail':historyDetail,revision,analysis,export:exportView,recovery};const content=['loading','error'].includes(s.scenario)?stateView(s.scenario):(views[s.view]??opening)();document.querySelector('#app').innerHTML=shell(content);updateURL();if(document.activeElement===document.body){const target=focusId?document.getElementById(focusId):focusGo?document.querySelector(`[data-hgo="${focusGo}"]`):focusScene?document.querySelector(`[data-hscene="${focusScene}"]`):focusUnit?document.querySelector(`[data-hunit="${focusUnit}"]`):null;target?.focus({preventScroll:true});}} 
function switchCase(id){if(s.staged.length){s.error='Apply or remove staged reviews before changing production. Their exact source context has been retained.';render();return;}captureDraft();s.caseId=id;s.epoch=s.epochs[id]??1;s.sceneId='S'+meta().first;s.unit=1;s.query='';s.page=0;s.menu=false;s.scenario='recorded';s.historyPage=0;s.view='opening';s.notice='';s.error='';render();}
function selectScene(id){captureDraft();const searchWasOpen=s.sceneMenu;s.sceneId=id;s.sceneMenu=false;s.error='';render();if(searchWasOpen){const title=document.querySelector('.h-page-title h1');title?.setAttribute('tabindex','-1');title?.focus();}}
async function verifySelection(){if(!s.staged.length)throw Error('Stage an exact-source review first.');for(const r of s.staged){const p=frozenCases.find(x=>x.case.id===r.caseId);if(!p||p.case.permitSha256!==r.sourceHash||p.case.permit.split('\n')[r.unit]!==r.quote||r.epoch!==s.epoch||s.scenario==='stale'||await digest(r.sceneRow)!==r.sceneHash)throw Error('This selection is stale. Inspect current sources and restage; no review was applied.');}return true;}
document.addEventListener('input',e=>{if(!active())return;if(e.target.closest('#h-review-form'))captureDraft();});
document.addEventListener('change',async e=>{if(!active())return;try{if(e.target.id==='h-scenario'){if(s.staged.length){s.error='Apply or remove staged reviews before changing the test context.';render();return;}captureDraft();s.scenario=e.target.value;s.query='';s.page=0;s.sceneId=realScenes()[0].id;s.unit=1;s.view=s.scenario==='empty'?'opening':s.view;s.verified=false;s.error='';render();}if(['h-mobile-scene','h-evidence-scene'].includes(e.target.id))selectScene(e.target.value);if(e.target.id==='h-source-unit'){captureDraft();s.unit=+e.target.value;render();}if(e.target.id==='h-work-filter'){s.workFilter=e.target.value;s.workPage=0;render();}if(e.target.id==='h-recovery-condition'){s.recovery=e.target.value;s.recoveryVerified=false;render();}if(e.target.id==='h-intake-file'){const file=e.target.files[0];if(!file)return;if(!/\.(txt|md)$/i.test(file.name)||file.size>250000)throw Error('Use a fictional .txt or .md file under 250 KB for this design intake.');const buffer=await file.arrayBuffer();const bytes=new Uint8Array(buffer);const sha256=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');s.intake={name:file.name,text:new TextDecoder('utf-8',{fatal:true}).decode(buffer),bytes:file.size,sha256,reviewed:false};persist();render();}}catch(err){s.error=err.message;render();}});
document.addEventListener('keydown',e=>{if(!active())return;if(e.target.id==='h-scene-search'&&e.key==='Enter'){e.preventDefault();s.query=e.target.value;s.page=0;render();document.querySelector('#h-scene-search')?.focus();}});
document.addEventListener('change',e=>{if(active()&&e.target.id==='h-scene-search'){s.query=e.target.value;s.page=0;render();}});
document.addEventListener('submit',async e=>{if(!active()||!e.target.id.startsWith('h-'))return;e.preventDefault();try{const d=new FormData(e.target);if(e.target.id==='h-review-form'){if(['long','stale'].includes(s.scenario))throw Error('This design source state cannot be applied to the original recording.');if(!String(d.get('reviewer')).trim()||String(d.get('reason')).trim().length<8)throw Error('Enter a reviewer name and a reason of at least eight characters.');const x=scene();const item={caseId:s.caseId,sceneId:x.id,sceneRow:x.row,sceneHash:await digest(x.row),unit:s.unit,quote:clauses()[s.unit],sourceHash:pack().case.permitSha256,ref:meta().ref,epoch:s.epoch,reviewer:String(d.get('reviewer')).trim(),decision:d.get('decision'),reason:String(d.get('reason')).trim(),prototypeOnly:true};const i=s.staged.findIndex(r=>r.caseId===item.caseId&&r.sceneId===item.sceneId&&r.unit===item.unit);if(i<0)s.staged.push(item);else s.staged[i]=item;s.verified=false;persist();go('preview');}if(e.target.id==='h-condition-form'){s.conditions[s.caseId+':'+s.selectedCondition]={reviewer:d.get('reviewer'),decision:d.get('decision'),reason:d.get('reason'),date:d.get('date'),timezone:d.get('timezone'),prototypeOnly:true};persist();s.notice='Prototype work recorded for the selected scene. This is not filming authority.';render();}if(e.target.id==='h-intake-form'){s.intake={...s.intake,reviewed:true,reviewer:d.get('reviewer')};persist();s.notice='Prototype transcription verification recorded. No production source store changed.';render();}if(e.target.id==='h-history-filter'){s.historyQuery=String(d.get('query')??'');s.historyKind=d.get('kind');s.historyPage=0;render();}if(e.target.id==='h-recovery-form'){if(d.get('identity')!==meta().name)throw Error('Type the exact sample production name before creating a separate design copy.');s.recovered.push({caseId:s.caseId,at:new Date().toISOString(),prototypeOnly:true});persist();s.notice='A separate design copy was recorded. No actual production was restored or overwritten.';render();}}catch(err){s.error=err.message;render();}});
document.addEventListener('click',async e=>{if(!active())return;const el=e.target.closest('button');if(!el)return;try{if(el.dataset.hscene){selectScene(el.dataset.hscene);return;}if(el.dataset.hunit){captureDraft();s.unit=+el.dataset.hunit;render();return;}if(el.dataset.hcondition){s.selectedCondition=el.dataset.hcondition;const w=workItems().find(x=>x.id===s.selectedCondition);s.sceneId=w.scene;s.unit=w.kind==='source'?3:2;go('condition');return;}if(el.dataset.hhistory){s.historySelected=el.dataset.hhistory;go('history-detail');return;}const cmd=el.dataset.hgo;if(!cmd)return;s.error='';s.notice='';if(cmd==='picker'){s.menu=!s.menu;render();return;}if(cmd.startsWith('case-')){switchCase(cmd.slice(5));return;}if(cmd==='empty'){if(s.staged.length)throw Error('Apply or remove staged reviews before opening an empty production.');s.scenario='empty';go('opening');return;}if(cmd==='reset-case'){s.scenario='recorded';go('discovery');return;}if(cmd==='toggle-scenes'){s.sceneMenu=!s.sceneMenu;render();if(s.sceneMenu)document.querySelector('#h-scene-search')?.focus();return;}if(cmd==='investigate-first'||cmd==='investigate-second'){s.sceneId='S'+(cmd==='investigate-first'?meta().first:meta().second);s.unit=cmd==='investigate-first'?2:3;go('discovery');return;}if(cmd==='scene-next'||cmd==='scene-prev'){s.page=Math.max(0,s.page+(cmd==='scene-next'?1:-1));render();return;}if(cmd==='work-next'||cmd==='work-prev'){s.workPage=Math.max(0,s.workPage+(cmd==='work-next'?1:-1));render();return;}if(cmd==='condition-scene'){go('discovery');return;}if(cmd==='verify'){await verifySelection();s.verified=true;s.notice='Exact staged source and scene selections verified in this design sandbox.';render();return;}if(cmd==='apply'){if(!s.verified)throw Error('Verify selected sources before applying. Staged reviews are retained.');await verifySelection();s.reviews.push(...s.staged.map(r=>({...r,at:new Date().toISOString()})));s.staged=[];s.verified=false;persist();s.view='history';s.notice='Prototype review applied. The original Clocked recording is unchanged.';render();const status=document.querySelector('[role="status"]');status?.setAttribute('tabindex','-1');status?.focus();return;}if(cmd.startsWith('remove-')){s.staged.splice(+cmd.slice(7),1);s.verified=false;persist();render();return;}if(cmd==='history-stress'){s.historyStress=!s.historyStress;s.historyPage=0;render();return;}if(cmd==='history-next'||cmd==='history-prev'){s.historyPage=Math.max(0,s.historyPage+(cmd==='history-next'?1:-1));render();return;}if(cmd==='revision-preview'){s.revisionPreview=true;render();return;}if(cmd==='revision-apply'){if(s.staged.length)throw Error('Apply or remove staged reviews before simulating a revision.');s.scenario='stale';s.epoch++;s.epochs[s.caseId]=s.epoch;s.verified=false;persist();go('discovery');return;}if(cmd==='recovery-verify'){s.recoveryVerified=true;render();return;}if(cmd==='download'){const data={schema:'beforeroll-design-v2-notes-only',prototypeOnly:true,reviews:s.reviews,conditions:s.conditions,frozenProviderRecordsUnchanged:true};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='BeforeRoll-editorial-studio-design-notes.json';a.click();URL.revokeObjectURL(url);s.notice='Design notes exported. This is not a production evidence pack or encrypted backup.';render();return;}go(cmd);}catch(err){s.error=err.message;render();}});
export function mountHybrid({screen,onScreenChange}){notifyScreen=onScreenChange;captureDraft();s.view=screen;const valid=scenes().some(x=>x.id===s.sceneId);if(!valid)s.sceneId=realScenes()[0].id;s.unit=Math.max(0,Math.min(3,s.unit));render();}
